$_MODULE['<{layerslider}prestashop>_ba82cbe6dc7a81f3d77fabb6d414c0ee'] = 'Usa URL relativas para las imágenes locales. Esta configuración podría ser importante al mover tu instalación de PS.'; // Use relative URLs for local images. This setting could be important when moving your PS installation.
$_MODULE['<{layerslider}prestashop>_c878cdf0cb53e7dbeb791eab13b84146'] = 'Permitir reiniciar diapositivas al redimensionar'; // Allow restarting slides on resize
