$_MODULE['<{layerslider}prestashop>_d9f1451d7e147a9d76732b903c85fd98'] = 'Usar atributo srcset'; // Use srcset attribute
$_MODULE['<{layerslider}prestashop>_d962a6678a6f57c0697bdba39433e0d7'] = 'El atributo srcset permite cargar imágenes escaladas dinámicamente según la resolución de la pantalla. Puede ahorrar ancho de banda y permitir el uso de imágenes retina-ready en dispositivos de alta resolución. En algunos casos extremos raros, esta opción podría causar imágenes borrosas.'; // The srcset attribute allows loading dynamically scaled images based on screen resolution. It can save bandwidth and allow using retina-ready images on high resolution devices. In some rare edge cases, this option might cause blurry images.
$_MODULE['<{layerslider}prestashop>_806790e901a729799c42f26b23c5470f'] = 'Carga diferida mejorada'; // Enhanced lazy load
$_MODULE['<{layerslider}prestashop>_bb477d8d7ee0d5561c80c51482d44904'] = 'El comportamiento de carga diferida predeterminado hace un compromiso para garantizar la máxima compatibilidad al tiempo que ofrece una solución que funciona idealmente en casi todos los casos. Sin embargo, al dejar intacto el atributo ’src’ de la imagen, existe una pequeña posibilidad de que el navegador comience a descargar algunos activos por una fracción de segundo antes de que Creative Slider los cancele. Habilitar esta opción eliminará cualquier posibilidad de generar incluso una cantidad minúscula de tráfico no deseado, pero también puede causar problemas para la indexación de los motores de búsqueda y otros temas/módulos.'; // The default lazy loading behavior makes a compromise to ensure maximum compatibility while offering a solution that works ideally in almost all cases. However, by leaving the image ’src’ attribute untouched, there is a slight chance that the browser might start downloading some assets for a split second before Creative Slider cancels them. Enabling this option will eliminate any chance of generating even a minuscule amount of unwanted traffic, but it can also cause issues for search engine indexing and other themes/modules.
$_MODULE['<{layerslider}prestashop>_451af3f11142c7626d839eb7674d3e0a'] = 'Preferir modo de fusión'; // Prefer Blend Mode
$_MODULE['<{layerslider}prestashop>_6da524b45307ee7baa37799db0cd4796'] = 'Habilita esta opción para evitar problemas de modo de fusión con las transiciones de diapositivas. Debido a limitaciones técnicas, esto también recortará tus transiciones de diapositivas independientemente de tu configuración.'; // Enable this option to avoid blend mode issues with slide transitions. Due to technical limitations, this will also clip your slide transitions regardless of your settings.
$_MODULE['<{layerslider}prestashop>_00d23a76e43b46dae9ec7aa9dcbebb32'] = 'Habilitado'; // Enabled
$_MODULE['<{layerslider}prestashop>_5e1575919121f7253b56bb39b99e1042'] = 'TuLogo'; // YourLogo
$_MODULE['<{layerslider}prestashop>_367a210257e2ea49914c4a695f8abf70'] = 'Se puede mostrar una capa de imagen fija sobre el slider que permanece inmóvil durante todo el slider. Se puede usar para mostrar logotipos o marcas de agua.'; // A fixed image layer can be shown above the slider that remains still throughout the whole slider. Can be used to display logos or watermarks.
$_MODULE['<{layerslider}prestashop>_77c34b7517dd216292658ee3b420dd1f'] = 'Estilo de TuLogo'; // YourLogo style
$_MODULE['<{layerslider}prestashop>_355a12e47302b7e2627dc90d1c0e79c6'] = 'Propiedades CSS para controlar la ubicación y apariencia de la imagen.'; // CSS properties to control the image placement and appearance.
$_MODULE['<{layerslider}prestashop>_1cfb56506d3621c27196a6aa02a23c39'] = 'Enlace de TuLogo'; // YourLogo link
$_MODULE['<{layerslider}prestashop>_7966bee26ee8f49f0c5693a3b25a3461'] = 'Ingresa una URL para enlazar la imagen de TuLogo.'; // Enter a URL to link the YourLogo image.
$_MODULE['<{layerslider}prestashop>_5afb14c537c0ed4ed3805e8f9c12ae68'] = 'Destino del enlace'; // Link target
$_MODULE['<{layerslider}prestashop>_61c717e4d8c25d8ea4fe003f88675e74'] = 'Abrir en la misma página'; // Open on the same page
$_MODULE['<{layerslider}prestashop>_98a0075b23373e991f18c15fb8442d8b'] = 'Abrir en una nueva página'; // Open on new page
$_MODULE['<{layerslider}prestashop>_67c48b3d90f5ae44e816fe1030452fb3'] = 'Abrir en el marco padre'; // Open in parent frame
$_MODULE['<{layerslider}prestashop>_e106bc3e705b4e24fe60a249e11c6f01'] = 'Abrir en el marco principal'; // Open in main frame
$_MODULE['<{layerslider}prestashop>_b77006f2d0398fa7e68ef1a893ef850c'] = 'ID de la publicación'; // Post ID
$_MODULE['<{layerslider}prestashop>_e4d99041f9e5af92b38767d09947600e'] = 'Título de la publicación'; // Post Title
$_MODULE['<{layerslider}prestashop>_b5e6d43af159d5d593ca7c4b6db55491'] = 'Número de comentarios'; // Number of Comments
$_MODULE['<{layerslider}prestashop>_cf3fb1ff52ea1eed3347ac5401ee7f0c'] = 'Ascendente'; // Ascending
$_MODULE['<{layerslider}prestashop>_e3cf5ac19407b1a62c6fccaff675a53b'] = 'Descendente'; // Descending
$_MODULE['<{layerslider}prestashop>_1a3cb622f5613168ed16ba4ffcfe49fe'] = 'Establecer una imagen de diapositiva'; // Set a slide image
$_MODULE['<{layerslider}prestashop>_1cf966e0716f7f365751df6e4a86f43f'] = 'La imagen/fondo de la diapositiva. Haz clic en la imagen para abrir el Administrador de imágenes y elegir o subir una imagen.'; // The slide image/background. Click on the image to open the Image Manager to choose or upload an image.
$_MODULE['<{layerslider}prestashop>_6f6cb72d544962fa333e2e34ce64f719'] = 'Tamaño'; // Size
$_MODULE['<{layerslider}prestashop>_13eac5a039bc8041315fe1165a245a98'] = 'El tamaño de la imagen de fondo de la diapositiva. Deja esta opción en heredar si quieres establecerla globalmente desde la Configuración del Slider.'; // The size of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_c49484faf79e2388b580e49444d6ac11'] = 'Heredar'; // Inherit
$_MODULE['<{layerslider}prestashop>_52f5e0bc3859bc5f5e25130b6c7e8881'] = 'Posición'; // Position
$_MODULE['<{layerslider}prestashop>_25824be059f35ecadb2d38a895f7e710'] = 'La posición de la imagen de fondo de la diapositiva. Deja esta opción en heredar si quieres establecerla globalmente desde la Configuración del Slider.'; // The position of the slide background image. Leave this option on inherit if you want to set it globally from Slider Settings.
$_MODULE['<{layerslider}prestashop>_cb5feb1b7314637725a2e73bdc9f7295'] = 'Color'; // Color
$_MODULE['<{layerslider}prestashop>_9880a2532d7550cb4bef6c24ce2275f3'] = 'El color de fondo de la diapositiva. Puedes usar nombres de colores, valores hexadecimales, RGB o RGBA.'; // The slide background color. You can use color names, hexadecimal, RGB or RGBA values.
$_MODULE['<{layerslider}prestashop>_9d8cfafeba857023956c26437b6570fc'] = 'Establecer una miniatura de diapositiva'; // Set a slide thumbnail
$_MODULE['<{layerslider}prestashop>_b95232d8c69a9f62cd6dab61887acf0f'] = 'La imagen en miniatura de esta diapositiva. Haz clic en la imagen para abrir el Administrador de imágenes y elegir o subir una imagen. Si dejas este campo vacío, se usará la imagen de la diapositiva.'; // The thumbnail image of this slide. Click on the image to open the Image Manager to choose or upload an image. If you leave this field empty, the slide image will be used.
$_MODULE['<{layerslider}prestashop>_e02d2ae03de9d493df2b6b2d2813d302'] = 'Duración'; // Duration
$_MODULE['<{layerslider}prestashop>_b0c71ca949422ff07096787e513bf3dc'] = 'Aquí puedes establecer el intervalo de tiempo entre los cambios de diapositiva, esta diapositiva permanecerá visible durante el tiempo especificado aquí. Este valor está en milisegundos, por lo que el valor 1000 significa 1 segundo. Por favor, no uses 0 o valores muy bajos.'; // Here you can set the time interval between slide changes, this slide will stay visible for the time specified here. This value is in millisecs, so the value 1000 means 1 second. Please don't use 0 or very low values.
$_MODULE['<{layerslider}prestashop>_4357cfb0b7acc1db400c94094794ae17'] = 'Hemos creado nuestras transiciones de diapositivas predefinidas con especial cuidado para que se ajusten a la mayoría de los casos de uso. Sin embargo, si deseas aumentar o disminuir la velocidad de estas transiciones, puedes anular su tiempo aquí proporcionando tu propia duración de transición en milisegundos. (1 segundo = 1000 milisegundos)'; // We've made our pre-defined slide transitions with special care to fit in most use cases. However, if you would like to increase or decrease the speed of these transitions, you can override their timing here by providing your own transition length in milliseconds. (1 second = 1000 milliseconds)
$_MODULE['<{layerslider}prestashop>_38912a644194123a9ee9d01e126fcfae'] = 'duración personalizada'; // custom duration
$_MODULE['<{layerslider}prestashop>_1605a4f4a4e45503d3ac914de9fba80a'] = 'Desplazamiento de tiempo'; // Time Shift
$_MODULE['<{layerslider}prestashop>_6d106138f5fadb601a337fca4d4b7a2e'] = 'Puedes desplazar el punto de inicio de la línea de tiempo de la animación de la diapositiva, para que las capas puedan animarse antes después de un cambio de diapositiva. Este valor está en milisegundos. Un segundo es 1000 milisegundos. Solo puedes usar un valor negativo.'; // You can shift the starting point of the slide animation timeline, so layers can animate in an earlier time after a slide change. This value is in milliseconds. A second is 1000 milliseconds. You can only use a negative value.
$_MODULE['<{layerslider}prestashop>_e1f70f4a4265cb51c1b219aa60eaa441'] = 'Ingresar URL'; // Enter URL
$_MODULE['<{layerslider}prestashop>_cfdb83fef5ccd56abb3592f98391b355'] = 'Si quieres enlazar toda la diapositiva, escribe la URL aquí. Puedes elegir una de las opciones predefinidas de la lista desplegable al hacer clic en este campo. También puedes escribir un signo de número seguido de un número para enlazar esta capa a otra diapositiva. Ejemplo: #3 - esto cambiará a la tercera diapositiva.'; // If you want to link the whole slide, type the URL here. You can choose one of the pre-defined options from the dropdown list when you click into this field. You can also type a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_1f7412ef1f7fdba3cc269af9a0b7a40c'] = 'Destino del enlace'; // Link Target
$_MODULE['<{layerslider}prestashop>_e82688575274fd1ba522f5044431cc93'] = 'Desplazar al elemento (Ingresar selector)'; // Scroll to element (Enter selector)
$_MODULE['<{layerslider}prestashop>_1fc71d8275be86e2787bc4a8f0d62c84'] = 'Elige si el enlace de la diapositiva debe estar encima o debajo de tus capas. La última opción hace que el enlace solo se pueda hacer clic en los espacios vacíos donde el fondo de la diapositiva es visible, y te permite enlazar tanto las diapositivas como las capas independientemente unas de otras.'; // Choose whether the slide link should be on top or underneath your layers. The later option makes the link clickable only at empty spaces where the slide background is visible, and enables you to link both slides and layers independently from each other.
$_MODULE['<{layerslider}prestashop>_7e04fe64ab136e31d62fcc6ea113f1ca'] = 'Encima de las capas'; // On top of layers
$_MODULE['<{layerslider}prestashop>_d722a275a3f48eb46d892c9df863e1af'] = 'Debajo de las capas'; // Underneath layers
$_MODULE['<{layerslider}prestashop>_739cea2b85156183f917f2ccaa10a50c'] = '#ID'; // #ID
$_MODULE['<{layerslider}prestashop>_06f695600f91bfbd579d9d8f5a0147bd'] = 'Puedes aplicar un atributo ID en el elemento HTML de esta diapositiva para trabajar con él en tu código CSS o Javascript personalizado.'; // You can apply an ID attribute on the HTML element of this slide to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_550dc007dba485adc22eddfe0af40a81'] = 'Enlace profundo'; // Deeplink
$_MODULE['<{layerslider}prestashop>_070cb374111546db9ae4642406963ebd'] = 'Puedes especificar un nombre de alias de diapositiva que puedes usar en tus URL con un signo de número, para que Creative Slider comience con la diapositiva correspondiente.'; // You can specify a slide alias name which you can use in your URLs with a hash mark, so Creative Slider will start with the correspondig slide.
$_MODULE['<{layerslider}prestashop>_436e4906cf91bb911a38eb161e858a69'] = 'Hover global'; // Global Hover
$_MODULE['<{layerslider}prestashop>_f22bc2f96ed30d26a29060598c44c2fa'] = 'Al activar esta opción, todas las capas activarán sus transiciones de hover al mismo tiempo cuando pases el cursor del ratón sobre el slider. Es útil para crear efectos espectaculares que involucran múltiples transiciones de capa y se activan al pasar el cursor sobre el slider en lugar de capas individuales.'; // By turning this option on, all layers will trigger their Hover Transitions at the same time when you hover over the slider with your mouse cursor. It’s useful to create spectacular effects that involve multiple layer transitions and activate on hovering over the slider instead of individual layers.
$_MODULE['<{layerslider}prestashop>_7acdf85c69cc3c5305456a293524386e'] = 'Oculto'; // Hidden
$_MODULE['<{layerslider}prestashop>_a494a9272210a3aa3682f9fa8b6ad9fc'] = 'Si no quieres usar esta diapositiva en tu página de inicio, pero quieres conservarla, puedes ocultarla con este interruptor.'; // If you don't want to use this slide in your front-page, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_d33fd48027b557f5bcb3f15a238d7537'] = 'Capas desbordantes'; // Overflow layers
$_MODULE['<{layerslider}prestashop>_5bbae9c02b64de11da4d22707a297710'] = 'Por defecto, el slider recorta las capas fuera de sus límites. Habilita esta opción para permitir contenido desbordante.'; // By default the slider clips the layers outside of its bounds. Enable this option to allow overflowing content.
$_MODULE['<{layerslider}prestashop>_57ffe7327fb6fb004c59466a978c4100'] = 'Empieza en'; // Start on
$_MODULE['<{layerslider}prestashop>_6ba9104be4da1fea318c02faca91dad6'] = 'La diapositiva programada solo será visible para tus visitantes durante el período de tiempo que establezcas aquí.<br>Estamos usando el formato de fecha y hora internacional para evitar ambigüedades.'; // Scheduled slide will only be visible to your visitors between the time period you set here.<br>We're using international date and time format to avoid ambiguity.
$_MODULE['<{layerslider}prestashop>_6ea6d7b483daeb9be3acaad212b04181'] = 'Termina en'; // Stop on
$_MODULE['<{layerslider}prestashop>_b78a3223503896721cca1303f776159b'] = 'Título'; // Title
$_MODULE['<{layerslider}prestashop>_a2e92861b757ab878312dd57993d60cf'] = 'Alt'; // Alt
$_MODULE['<{layerslider}prestashop>_f17b29e841d3183298a453dc423242a0'] = 'Nombra o describe la imagen de tu diapositiva, para que los motores de búsqueda y los programas de lectura de pantalla puedan identificarla correctamente.'; // Name or describe your slide image, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_4252b72e6ebcd4d4b4c2e46a786f03d2'] = 'Zoom'; // Zoom
$_MODULE['<{layerslider}prestashop>_f5ca4abce85e2dddb0342d0bae3a7270'] = 'Acercar'; // Zoom In
$_MODULE['<{layerslider}prestashop>_30850b501f98539b1aabaa29fabe41ef'] = 'Alejar'; // Zoom Out
$_MODULE['<{layerslider}prestashop>_8d2de5368588552fbae54044ac5c7b3d'] = 'Rotar'; // Rotate
$_MODULE['<{layerslider}prestashop>_8aa2fa2e684ba408f551f3504c47427e'] = 'La cantidad de rotación (si la hay) en grados utilizada en el efecto Ken Burns. Se permiten valores negativos para la rotación en sentido contrario a las agujas del reloj.'; // The amount of rotation (if any) in degrees used in the Ken Burns effect. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_85a7cd587d6142dbfc1a4de05af7b75d'] = 'Escala'; // Scale
$_MODULE['<{layerslider}prestashop>_2ed8e1d37be922f23b2713c3e69a85ae'] = 'Aumenta o disminuye el tamaño de la imagen de fondo de la diapositiva en el efecto Ken Burns. El valor predeterminado es 1, el valor 2 duplicará la imagen, mientras que 0.5 da como resultado la mitad del tamaño. Los valores negativos voltearán la imagen.'; // Increase or decrease the size of the slide background image in the Ken Burns effect. The default value is 1, the value 2 will double the image, while 0.5 results half the size. Negative values will flip the image.
$_MODULE['<{layerslider}prestashop>_a1fa27779242b4902f7ae3bdd5c6d508'] = 'Tipo'; // Type
$_MODULE['<{layerslider}prestashop>_4a2d97fd5296d09fea3cbe45d107a7b3'] = 'El valor predeterminado para las capas de paralaje en esta diapositiva, que heredarán, a menos que lo establezcas de otra manera en las capas afectadas.'; // The default value for parallax layers on this slide, which they will inherit, unless you set it otherwise on the affected layers.
$_MODULE['<{layerslider}prestashop>_8c94134f25efe7680f9743b2774e8e1f'] = '2D'; // 2D
$_MODULE['<{layerslider}prestashop>_76aa96369abbba52e621bfa83da8e64f'] = '3D'; // 3D
$_MODULE['<{layerslider}prestashop>_a4ecfc70574394990cf17bd83df499f7'] = 'Evento'; // Event
$_MODULE['<{layerslider}prestashop>_87932092d26d18e63889036bbf70518e'] = 'Puedes activar el efecto de paralaje ya sea desplazando la página, o moviendo el cursor del ratón / inclinando tu dispositivo móvil. Este es el valor predeterminado en esta diapositiva, que las capas de paralaje heredarán, a menos que lo establezcas de otra manera directamente en ellas.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_58af070b9f7f3dc090af0ece708e8869'] = 'Cursor o Inclinación'; // Cursor or Tilt
$_MODULE['<{layerslider}prestashop>_61ca8fa7a7c8b4699523bc8773c306d0'] = 'Ejes'; // Axes
$_MODULE['<{layerslider}prestashop>_fc888362a84b5b975136bbca8e1fc5c6'] = 'Elige en qué ejes deben moverse las capas de paralaje. Este es el valor predeterminado en esta diapositiva, que las capas de paralaje heredarán, a menos que lo establezcas de otra manera directamente en ellas.'; // Choose on which axes parallax layers should move. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_6adf97f83acf6453d4a6a4b1070f3754'] = 'Ninguno'; // None
$_MODULE['<{layerslider}prestashop>_2c452204ed58a6f4a3bcda80344b338a'] = 'Ambos ejes'; // Both axes
$_MODULE['<{layerslider}prestashop>_ad09aaae9c9ffe403ffdb2a6568f5a36'] = 'Solo horizontal'; // Horizontal only
$_MODULE['<{layerslider}prestashop>_354908b89248f3dcbab970b32860a331'] = 'Solo vertical'; // Vertical only
$_MODULE['<{layerslider}prestashop>_8b622b0a6ecf4e0116eaf248876f8700'] = 'Origen de la transformación'; // Transform Origin
$_MODULE['<{layerslider}prestashop>_e5a904ff73268b65730e4fb8b6127bf1'] = 'Establece un punto en el lienzo desde el cual se calculan las transformaciones. Por ejemplo, una capa puede rotar alrededor de su eje central o un punto completamente personalizado, como una de sus esquinas. Los tres valores representan los ejes X, Y y Z en el espacio 3D. Además de los valores en píxeles y porcentajes, también puedes usar las siguientes constantes: top, right, bottom, left, center.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center.
$_MODULE['<{layerslider}prestashop>_97289d779de759c4fe3a0ef9d3a4ff3d'] = 'Duración del movimiento'; // Move duration
$_MODULE['<{layerslider}prestashop>_ef82e470cae5696da7dc47e9a50fa8f7'] = 'Controla la velocidad de animación de las capas cuando mueves el cursor del ratón o inclinas tu dispositivo móvil. Este es el valor predeterminado en esta diapositiva, que las capas de paralaje heredarán, a menos que lo establezcas de otra manera directamente en ellas.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0bdd8970e06688e4a6ad694b8ed7b9f7'] = 'Duración de salida'; // Leave duration
$_MODULE['<{layerslider}prestashop>_9aa9b8945ad7ff74e04fb53dbbe3d1f2'] = 'Controla la rapidez con que tus capas vuelven a su posición original cuando mueves el cursor del ratón fuera de un slider de paralaje. Este valor está en milisegundos. 1 segundo = 1000 milisegundos. Este es el valor predeterminado en esta diapositiva, que las capas de paralaje heredarán, a menos que lo establezcas de otra manera directamente en ellas.'; // Controls how quickly your layers revert to their original position when you move your mouse cursor outside of a parallax slider. This value is in milliseconds. 1 second = 1000 milliseconds. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_0aa6f4210bf373c95eda00232e93cd98'] = 'Distancia'; // Distance
$_MODULE['<{layerslider}prestashop>_396950a091a406fcd6f9f4cc75927536'] = 'Aumenta o disminuye la cantidad de movimiento de la capa al mover el cursor del ratón o inclinar un dispositivo móvil. Este es el valor predeterminado en esta diapositiva, que las capas de paralaje heredarán, a menos que lo establezcas de otra manera directamente en ellas.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_f1a42bd417390fc63b030a519624607a'] = 'Rotación'; // Rotation
$_MODULE['<{layerslider}prestashop>_331ee65576c7333ba77a13d691219105'] = 'Aumenta o disminuye la cantidad de rotación de la capa en el espacio 3D al mover el cursor del ratón o inclinar un dispositivo móvil. Este es el valor predeterminado en esta diapositiva, que las capas de paralaje heredarán, a menos que lo establezcas de otra manera directamente en ellas.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_a80420eef88d11f77532f1b9cb467fa3'] = 'Perspectiva'; // Perspective
$_MODULE['<{layerslider}prestashop>_7ba7448042bdf18c7669bec909a0a7be'] = 'Cambia la perspectiva de las capas en el espacio 3D. Este es el valor predeterminado en esta diapositiva, que las capas de paralaje heredarán, a menos que lo establezcas de otra manera directamente en ellas.'; // Changes the perspective of layers in the 3D space. This is the default value on this slide, which parallax layers will inherit, unless you set it otherwise directly on them.
$_MODULE['<{layerslider}prestashop>_d6432a4413208eee54d613ceb82f726a'] = 'Filtro Desde'; // Filter From
$_MODULE['<{layerslider}prestashop>_bd3ec381eecf6eb78c9a97594745d33c'] = 'Los filtros proporcionan efectos como desenfoque o cambio de color en tus capas. Haz clic en el campo de texto para ver una selección de filtros que puedes usar. Aunque al hacer clic en las opciones predefinidas se restablecerá el campo de texto, puedes aplicar múltiples filtros simplemente proporcionando una lista separada por espacios de todos los filtros que deseas usar.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use.
$_MODULE['<{layerslider}prestashop>_6b770358764a885d6dc7f2be20604356'] = 'Filtro Hasta'; // Filter To
$_MODULE['<{layerslider}prestashop>_05b1dc77590105a18fc4c02526fe0c7a'] = 'Autoplay'; // Autoplay
$_MODULE['<{layerslider}prestashop>_2b3de50de6ab7bd0aaf46ae654032790'] = 'Mostrar Info'; // Show Info
$_MODULE['<{layerslider}prestashop>_24b6472fcfa59cddd3f7bbc326582b5f'] = 'Controles'; // Controls
$_MODULE['<{layerslider}prestashop>_58bccbc47e6de6783fb90fd62890a171'] = 'Modo de relleno'; // Fill mode
$_MODULE['<{layerslider}prestashop>_bd7a9717d29c5ddcab1bc175eda1e298'] = 'Volumen'; // Volume
$_MODULE['<{layerslider}prestashop>_56a7f02a3b02e4a16864670ff48745e1'] = 'Usar este vídeo como fondo de la diapositiva'; // Use this video as slide background
$_MODULE['<{layerslider}prestashop>_4ee3787bc7df95d25272524868e60d4d'] = 'Fuerza a esta capa a actuar como el fondo de la diapositiva cubriendo todo el slider e ignorando algunas transiciones. Por favor, asegúrate de proporcionar tu propia imagen de póster con la opción de arriba, para que el slider pueda mostrarla inmediatamente al cargar la página.'; // Forces this layer to act like the slide background by covering the whole slider and ignoring some transitions. Please make sure to provide your own poster image with the option above, so the slider can display it immediately on page load.
$_MODULE['<{layerslider}prestashop>_9d16dd63ee0afa947dc998fb3d5a4a96'] = 'Elige una imagen de superposición:'; // Choose an overlay image:
$_MODULE['<{layerslider}prestashop>_e13b4cc51565c9030f943e31c253c8aa'] = 'Cubre tus vídeos con una imagen de superposición para tener efectos de puntos o rayas sobre ellos.'; // Cover your videos with an overlay image to have dotted or striped effects on them.
$_MODULE['<{layerslider}prestashop>_1529fb44e04df26ff7666faa9f58c605'] = 'DesplazamientoX'; // OffsetX
$_MODULE['<{layerslider}prestashop>_0d12fb40782d7877c5018ff4b501e701'] = 'Desplaza la posición inicial de la capa desde su original en el eje horizontal con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa. Los valores \'left\' o \'right\' posicionan la capa fuera del área de preparación, para que entre en la escena desde cualquier lado al animarse a su ubicación de destino.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it enters the scene from either side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_1508a7d829d65cf5e117fdc2aca0f155'] = 'DesplazamientoY'; // OffsetY
$_MODULE['<{layerslider}prestashop>_c91f704c049f7d06fe50106d7452c21c'] = 'Desplaza la posición inicial de la capa desde su original en el eje vertical con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos a la altura de esta capa. Los valores \'top\' o \'bottom\' posicionan la capa fuera del área de preparación, para que entre en la escena desde cualquier lado vertical al animarse a su ubicación de destino.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it enters the scene from either vertical side when animating to its destination location.
$_MODULE['<{layerslider}prestashop>_7686cf30c00c9f146a9224a33ba99a0f'] = 'La duración de la transición en milisegundos cuando la capa entra en la escena. Un segundo equivale a 1000 milisegundos.'; // The length of the transition in milliseconds when the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_f2572c86c0aff2b2b7a92fbb6dee1491'] = 'Empieza en'; // Start at
$_MODULE['<{layerslider}prestashop>_1f413844a6a15351c7a32a16ce962bfd'] = 'Retrasa la transición con la cantidad de milisegundos dada antes de que la capa entre en la escena. Un segundo equivale a 1000 milisegundos.'; // Delays the transition with the given amount of milliseconds before the layer enters the scene. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_32485d52ad7aea25b3bc80d416e76a3b'] = 'Easing'; // Easing
$_MODULE['<{layerslider}prestashop>_ca9a3cf0ea2e65cd611fe23633cd1186'] = 'La función de temporización de la animación. Con esta función puedes manipular el movimiento del objeto animado. Por favor, haz clic en el enlace junto a este campo de selección para abrir easings.net para más información y ejemplos en tiempo real.'; // The timing function of the animation. With this function you can manipulate the movement of the animated object. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_04e0385c10aefee8e4681617d2f3ef40'] = 'Fundido'; // Fade
$_MODULE['<{layerslider}prestashop>_ecdc93d174113fe69b7cbf2c42b5a1cb'] = 'Atenúa la capa durante la transición.'; // Fade the layer during the transition.
$_MODULE['<{layerslider}prestashop>_b98c4145f7f66383ce71bf31bc4850b2'] = 'Rota la capa según el número de grados dado. Se permiten valores negativos para la rotación en sentido contrario a las agujas del reloj.'; // Rotates the layer by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_801e0dd823542f625e0f2ee135efb62d'] = 'RotarX'; // RotateX
$_MODULE['<{layerslider}prestashop>_54f64742da0d7bd157ccaf54d4ac73a1'] = 'Rota la capa a lo largo del eje X (horizontal) según el número de grados dado. Se permiten valores negativos para la dirección inversa.'; // Rotates the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_ea0928ab345567847020e1544892fba0'] = 'RotarY'; // RotateY
$_MODULE['<{layerslider}prestashop>_209eea8f9d8a60293098e07e8951e156'] = 'Rota la capa a lo largo del eje Y (vertical) según el número de grados dado. Se permiten valores negativos para la dirección inversa.'; // Rotates the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_5a013b463ee01be2924568775fdddfb1'] = 'InclinarX'; // SkewX
$_MODULE['<{layerslider}prestashop>_253108f96bfad9912bb2178a4c7aef73'] = 'Inclina la capa a lo largo del eje X (horizontal) según el número de grados dado. Se permiten valores negativos para la dirección inversa.'; // Skews the layer along the X (horizontal) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_eeb66258f8bf4bb3c0763461b5c1797d'] = 'InclinarY'; // SkewY
$_MODULE['<{layerslider}prestashop>_9d19b1698a8b2f7b0efa8c91067053dd'] = 'Inclina la capa a lo largo del eje Y (vertical) según el número de grados dado. Se permiten valores negativos para la dirección inversa.'; // Skews the layer along the Y (vertical) by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_b5e0c179725e7f282ffb8e6a96797b49'] = 'EscalaX'; // ScaleX
$_MODULE['<{layerslider}prestashop>_15cfa2ea26e51b8489ace013f1b2ec5c'] = 'Escala la capa a lo largo del eje X (horizontal) por el vector especificado. Usa el valor 1 para el tamaño original. El valor 2 duplicará, mientras que 0.5 encogerá la capa en comparación con su tamaño original.'; // Scales the layer along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_3475b72c6483a5c871d245e2567c96c7'] = 'EscalaY'; // ScaleY
$_MODULE['<{layerslider}prestashop>_3db72901337b8e6eeaa04ffd8db52e5e'] = 'Escala la capa a lo largo del eje Y (vertical) por el vector especificado. Usa el valor 1 para el tamaño original. El valor 2 duplicará, mientras que 0.5 encogerá la capa en comparación con su tamaño original.'; // Scales the layer along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks the layer compared to its original size.
$_MODULE['<{layerslider}prestashop>_e55d5d854ca64aed330e5591b62ae112'] = 'Establece un punto en el lienzo desde el cual se calculan las transformaciones. Por ejemplo, una capa puede rotar alrededor de su eje central o un punto completamente personalizado, como una de sus esquinas. Los tres valores representan los ejes X, Y y Z en el espacio 3D. Además de los valores en píxeles y porcentajes, también puedes usar las siguientes constantes: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.'; // Sets a point on canvas from which transformations are calculated. For example, a layer may rotate around its center axis or a completely custom point, such as one of its corners. The three values represent the X, Y and Z axes in 3D space. Apart from the pixel and percentage values, you can also use the following constants: top, right, bottom, left, center, slidercenter, slidermiddle, slidertop, sliderright, sliderbottom, sliderleft.
$_MODULE['<{layerslider}prestashop>_4a18312b5b75f549d5551e5912ad6ebf'] = 'Máscara'; // Mask
$_MODULE['<{layerslider}prestashop>_7fb23cb4a33cca7e266b2deda0034711'] = 'Recorta (corta) los lados de la capa por la cantidad especificada en píxeles o porcentajes. Los 4 valores en orden: arriba, derecha, abajo y el lado izquierdo de la capa.'; // Clips (cuts off) the sides of the layer by the given amount specified in pixels or percentages. The 4 value in order: top, right, bottom and the left side of the layer.
$_MODULE['<{layerslider}prestashop>_a9ded1e5ce5d75814730bb4caaf49419'] = 'Fondo'; // Background
$_MODULE['<{layerslider}prestashop>_57315a787bf5df775dcdb38f85aacf7b'] = 'El color de fondo de tu capa. Puedes usar nombres de colores, valores hexadecimales, RGB o RGBA, así como la palabra clave \'transparent\'. Ejemplo: #FFF'; // The background color of your layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_cdb3e9cc0b2932a6d1543d19732761f1'] = 'El color de tu texto. Puedes usar nombres de colores, valores hexadecimales, RGB o RGBA. Ejemplo: #333'; // The color of your text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_cabcfc0f365f0e649cf8c229bf54605e'] = 'Esquinas redondeadas'; // Rounded Corners
$_MODULE['<{layerslider}prestashop>_f0d205bfae354c2e65725ed59bc101e7'] = 'Si quieres esquinas redondeadas, puedes establecer su radio aquí en píxeles. Ejemplo: 5px'; // If you want rounded corners, you can set its radius here in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_32954654ac8fe66a1d09be19001de2d4'] = 'Ancho'; // Width
$_MODULE['<{layerslider}prestashop>_de11d49b6bbf1b1ecd2b424dc1c0c74a'] = 'El ancho inicial de esta capa desde el cual se animará a su tamaño adecuado durante la transición.'; // The initial width of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_eec6c4bdbd339edf8cbea68becb85244'] = 'Altura'; // Height
$_MODULE['<{layerslider}prestashop>_4cc10791b724542e8a9a04636995d1f5'] = 'La altura inicial de esta capa desde la cual se animará a su tamaño adecuado durante la transición.'; // The initial height of this layer from which it will be animated to its proper size during the transition.
$_MODULE['<{layerslider}prestashop>_d7778d0c64b6ba21494c97f77a66885a'] = 'Filtro'; // Filter
$_MODULE['<{layerslider}prestashop>_3f6230752680291a660faeec55dc0b73'] = 'Los filtros proporcionan efectos como desenfoque o cambio de color en tus capas. Haz clic en el campo de texto para ver una selección de filtros que puedes usar. Aunque al hacer clic en las opciones predefinidas se restablecerá el campo de texto, puedes aplicar múltiples filtros simplemente proporcionando una lista separada por espacios de todos los filtros que deseas usar. Haz clic en el enlace "Filtro" para más información.'; // Filters provide effects like blurring or color shifting your layers. Click into the text field to see a selection of filters you can use. Although clicking on the pre-defined options will reset the text field, you can apply multiple filters simply by providing a space separated list of all the filters you would like to use. Click on the "Filter" link for more information.
$_MODULE['<{layerslider}prestashop>_8cb8ac2653a6471f6779aa5c2d9cded2'] = 'Cambia la perspectiva de esta capa en el espacio 3D.'; // Changes the perspective of this layer in the 3D space.
$_MODULE['<{layerslider}prestashop>_cb1fa274044590e8c05e0e3fe44dd203'] = 'Desplaza la capa desde su posición original en el eje horizontal con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa. Los valores \'left\' o \'right\' animan la capa fuera del área de preparación, para que pueda salir de la escena por cualquier lado.'; // Shifts the layer from its original position on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' animate the layer out the staging area, so it can leave the scene on either side.
$_MODULE['<{layerslider}prestashop>_aa243196666cd7d2c5e92dd0f8b9b5f4'] = 'Desplaza la capa desde su posición original en el eje vertical con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos a la altura de esta capa. Los valores \'top\' o \'bottom\' animan la capa fuera del área de preparación, para que pueda salir de la escena por cualquier lado vertical.'; // Shifts the layer from its original position on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' animate the layer out the staging area, so it can leave the scene on either vertical side.
$_MODULE['<{layerslider}prestashop>_f04f3b646758fcab3a12facb6373fdc0'] = 'La duración de la transición en milisegundos cuando la capa sale de la diapositiva. Un segundo equivale a 1000 milisegundos.'; // The length of the transition in milliseconds when the layer leaves the slide. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_b92bb5e60806c72def5363a5a8bb035e'] = 'Puedes establecer la hora de inicio de esta transición. Usa una de las opciones predefinidas para usar un tiempo relativo, que se puede desplazar con operaciones personalizadas.'; // You can set the starting time of this transition. Use one of the pre-defined options to use relative timing, which can be shifted with custom operations.
$_MODULE['<{layerslider}prestashop>_c36ace66cf4777473ba3200cf815253c'] = 'El cambio de diapositiva comienza (ignorando el modificador)'; // Slide change starts (ignoring modifier)
