$_MODULE['<{layerslider}prestashop>_8920002666c88ed85ae80665159154f4'] = 'La transición de texto de apertura comienza'; // Opening Text Transition starts
$_MODULE['<{layerslider}prestashop>_284f03773b79e8472a3798c95c4b9f63'] = 'La transición de texto de apertura se completa'; // Opening Text Transition completes
