$_MODULE['<{layerslider}prestashop>_7094fc088dddef6adaa665620fe96dcc'] = 'Inclina la capa a lo largo del eje X (horizontal) según el número de grados dado. Se permiten valores negativos para la dirección inversa.'; // Skews the layer along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_049d4369eb664418bd75569e09641c99'] = 'Inclina la capa a lo largo del eje Y (vertical) según el número de grados dado. Se permiten valores negativos para la dirección inversa.'; // Skews the layer along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction.
$_MODULE['<{layerslider}prestashop>_e9e245065a77b7927aaccb2cf9d2ffcd'] = 'Si no quieres usar esta capa, pero quieres conservarla, puedes ocultarla con este interruptor.'; // If you don't want to use this layer, but you want to keep it, you can hide it with this switch.
$_MODULE['<{layerslider}prestashop>_630c4a18856c4ae057355c9398e83a32'] = 'Anima el fondo hacia el color que especifiques aquí cuando la capa sale del lienzo del slider.'; // Animates the background toward the color you specify here when the layer leaves the slider canvas.
$_MODULE['<{layerslider}prestashop>_77064060d521c47a027e25dab869772f'] = 'Anima el color del texto hacia el color que especifiques aquí cuando la capa sale del lienzo del slider.'; // Animates the text color toward the color you specify here when the layer leaves the slider canvas.
