$_MODULE['<{layerslider}prestashop>_19c45324c9ca36d31215f056839a28c8'] = 'Desplazamiento de entrada'; // Shift In
$_MODULE['<{layerslider}prestashop>_02f41f49726759b91cf468825bdf41a2'] = 'Retrasa la transición de cada nodo de texto en relación con los demás. Un segundo equivale a 1000 milisegundos.'; // Delays the transition of each text nodes relative to each other. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_3fff50b68e60ed555ff901b0fdfcd783'] = 'Desplaza la posición inicial de los nodos de texto desde su original en el eje horizontal con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa. Los valores \'left\' o \'right\' posicionan los nodos de texto fuera del área de preparación, para que entren en la escena desde cualquier lado al animarse a su ubicación de destino. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Shifts the starting position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they enter the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_e1d2fdcc944aa0f2e839f171f044d659'] = 'Desplaza la posición inicial de los nodos de texto desde su original en el eje vertical con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa. Los valores \'top\' o \'bottom\' posicionan los nodos de texto fuera del área de preparación, para que entren en la escena desde cualquier lado vertical al animarse a su ubicación de destino. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Shifts the starting position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they enter the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_968c58d8f1922a6b84d393c59a64a49c'] = 'La duración de la transición en milisegundos de los fragmentos de texto individuales. Un segundo equivale a 1000 milisegundos.'; // The transition length in milliseconds of the individual text fragments. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_ca6c773be9bea589e35cd5932032450e'] = 'La función de temporización de la animación. Con esta función puedes manipular el movimiento de los fragmentos de texto animados. Por favor, haz clic en el enlace junto a este campo de selección para abrir easings.net para más información y ejemplos en tiempo real.'; // The timing function of the animation. With this function you can manipulate the movement of animated text fragments. Please click on the link next to this select field to open easings.net for more information and real-time examples.
$_MODULE['<{layerslider}prestashop>_218ff9f345230b14660e70e66162823f'] = 'Atenúa los fragmentos de texto durante su transición.'; // Fade the text fragments during their transition.
$_MODULE['<{layerslider}prestashop>_87140560d2ebde43c1ee6bcbca46632b'] = 'ComienzaEn'; // StartAt
$_MODULE['<{layerslider}prestashop>_5ca3eda902c20e71f2b8a9b37d6400e9'] = 'La transición de apertura comienza'; // Opening Transition starts
$_MODULE['<{layerslider}prestashop>_fff3063495dd33cf3909fa4b1a9bc98d'] = 'Rota los fragmentos de texto en el sentido de las agujas del reloj según el número de grados dado. Se permiten valores negativos para la rotación en sentido contrario a las agujas del reloj. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Rotates text fragments clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_14f1aa4b97984dfcc375079b84f0eccc'] = 'Rota los fragmentos de texto a lo largo del eje X (horizontal) según el número de grados dado. Se permiten valores negativos para la dirección inversa. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Rotates text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_871c9bdc8e8606162c54996b7f3e3d55'] = 'Rota los fragmentos de texto a lo largo del eje Y (vertical) según el número de grados dado. Se permiten valores negativos para la dirección inversa. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Rotates text fragments along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_fd776f8e6385f4f4e57c79701beb1f12'] = 'Escala los fragmentos de texto a lo largo del eje X (horizontal) por el vector especificado. Usa el valor 1 para el tamaño original. El valor 2 duplicará, mientras que 0.5 encogerá los fragmentos de texto en comparación con su tamaño original. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Scales text fragments along the X (horizontal) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_b95364eee0d39f1ff08c9511fd007c3b'] = 'Escala los fragmentos de texto a lo largo del eje Y (vertical) por el vector especificado. Usa el valor 1 para el tamaño original. El valor 2 duplicará, mientras que 0.5 encogerá los fragmentos de texto en comparación con su tamaño original. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Scales text fragments along the Y (vertical) axis by the specified vector. Use the value 1 for the original size. The value 2 will double, while 0.5 shrinks text fragments compared to their original size. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_eec138a9b01bfa45053a9c2e34cc012a'] = 'Inclina los fragmentos de texto a lo largo del eje X (horizontal) según el número de grados dado. Se permiten valores negativos para la dirección inversa. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Skews text fragments along the X (horizontal) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_0e34f559e062c73fd9f20e88a6f2dff9'] = 'Inclina los fragmentos de texto a lo largo del eje Y (vertical) según el número de grados dado. Se permiten valores negativos para la dirección inversa. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Skews text fragments along the Y (vertical) axis by the given number of degrees. Negative values are allowed for reverse direction. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_5160493a371ec5eaac86b380847e5df5'] = 'Desplazamiento de salida'; // Shift Out
$_MODULE['<{layerslider}prestashop>_ef90ee89ac37b9e0f7d58c40106d0489'] = 'Desplaza la posición final de los nodos de texto desde su original en el eje horizontal con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa. Los valores \'left\' o \'right\' posicionan los nodos de texto fuera del área de preparación, para que salgan de la escena desde cualquier lado al animarse a su ubicación de destino. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Shifts the ending position of text nodes from their original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position text nodes out the staging area, so they leave the scene from either side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_a7dd960d399567a046b0614242132a75'] = 'Desplaza la posición final de los nodos de texto desde su original en el eje vertical con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa. Los valores \'top\' o \'bottom\' posicionan los nodos de texto fuera del área de preparación, para que salgan de la escena desde cualquier lado vertical al animarse a su ubicación de destino. Al enumerar múltiples valores separados por un carácter |, el slider usará diferentes variaciones de transición en cada nodo de texto al ciclar entre los valores proporcionados.'; // Shifts the ending position of text nodes from their original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'top' or 'bottom' position text nodes out the staging area, so they leave the scene from either vertical side when animating to their destination location. By listing multiple values separated with a | character, the slider will use different transition variations on each text node by cycling between the provided values.
$_MODULE['<{layerslider}prestashop>_d3dd82ed2edaeee8b285d11df248cc2e'] = 'Desplaza la posición inicial de la capa desde su original en el eje horizontal con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa. Los valores \'left\' o \'right\' posicionan la capa fuera del área de preparación, para que pueda salir y volver a entrar en la escena desde cualquier lado durante la transición.'; // Shifts the layer starting position from its original on the horizontal axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer. The values 'left' or 'right' position the layer out the staging area, so it can leave and re-enter the scene from either side during the transition.
$_MODULE['<{layerslider}prestashop>_ad02c3d94f8b3590b135be78e2f8e69f'] = 'Desplaza la posición inicial de la capa desde su original en el eje vertical con el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos a la altura de esta capa. Los valores \'top\' o \'bottom\' posicionan la capa fuera del área de preparación, para que pueda salir y volver a entrar en la escena desde cualquier lado vertical durante la transición.'; // Shifts the layer starting position from its original on the vertical axis with the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the height of this layer. The values 'top' or 'bottom' position the layer out the staging area, so it can leave and re-enter the scene from either vertical side during the transition.
$_MODULE['<{layerslider}prestashop>_7c1780aa74c2a852b5de424e51739b08'] = 'La duración de la transición en milisegundos. Un segundo es igual a 1000 milisegundos.'; // The length of the transition in milliseconds. A second is equal to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_c405823ea6eef48b12c76d719743050e'] = 'La función de temporización de la animación para manipular el movimiento de la capa. Haz clic en el enlace junto a este campo para abrir easings.net para ejemplos y más información.'; // The timing function of the animation to manipualte the layer's movement. Click on the link next to this field to open easings.net for examples and more information
$_MODULE['<{layerslider}prestashop>_bad6a5dd8c28e6b14f8e986615e3dc98'] = 'Opacidad'; // Opacity
$_MODULE['<{layerslider}prestashop>_52d096db2d41c73e647fc7b4afe9f4fb'] = 'Atenúa la capa. Puedes usar valores entre 1 y 0 para establecer la capa completamente opaca o transparente, respectivamente. Por ejemplo, el valor 0.5 hará que la capa sea semitransparente.'; // Fades the layer. You can use values between 1 and 0 to set the layer fully opaque or transparent respectively. For example, the value 0.5 will make the layer semi-transparent.
$_MODULE['<{layerslider}prestashop>_e93f994f01c537c4e2f7d8528c3eb5e9'] = 'Conteo'; // Count
$_MODULE['<{layerslider}prestashop>_dc9335e13408a714d8e29bf6e5b4af65'] = 'El número de veces que se repite la transición de bucle. El conteo incluye la parte inversa de las transiciones cuando usas la función Yoyo. Usa el valor -1 para repetir infinitamente o cero para deshabilitar el bucle.'; // The number of times repeating the Loop transition. The count includes the reverse part of the transitions when you use the Yoyo feature. Use the value -1 to repeat infinitely or zero to disable looping.
$_MODULE['<{layerslider}prestashop>_0f68101772bd5397ef8eb1b632798652'] = 'Espera'; // Wait
$_MODULE['<{layerslider}prestashop>_a2dd61cfcfc0bbdf8e5d0bacf03a4bfe'] = 'Tiempo de espera entre repeticiones en milisegundos. Un segundo es 1000 milisegundos.'; // Waiting time between repeats in milliseconds. A second is 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_7eebb65ba3f2d0b0d5ca4135a1291800'] = 'Yoyo'; // Yoyo
$_MODULE['<{layerslider}prestashop>_d2157b3302d4ec2fb08023a69d4568fd'] = 'Habilita esta opción para permitir la transición inversa, para que puedas hacer un bucle de ida y vuelta sin problemas.'; // Enable this option to allow reverse transition, so you can loop back and forth seamlessly.
$_MODULE['<{layerslider}prestashop>_0211cac74bd72aaae2f7886b1cbde16f'] = 'Mueve la capa horizontalmente según el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa.'; // Moves the layer horizontally by the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer.
$_MODULE['<{layerslider}prestashop>_780daa5a10788add2c24feda0a7046c9'] = 'Mueve la capa verticalmente según el número de píxeles dado. Usa valores negativos para la dirección opuesta. Los valores porcentuales son relativos al ancho de esta capa.'; // Moves the layer vertically by the given number of pixels. Use negative values for the opposite direction. Percentage values are relative to the width of this layer.
$_MODULE['<{layerslider}prestashop>_70f03c22e8756d36e8ebebf24fc83e68'] = 'Duración<br>inversa'; // Reverse<br>duration
$_MODULE['<{layerslider}prestashop>_f611f13e9d52fe21bddfa2b3c9c6e90a'] = 'La duración de la transición inversa en milisegundos. Un segundo es igual a 1000 milisegundos.'; // The duration of the reverse transition in milliseconds. A second is equal to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_36883b3adac19e03ce6e8258a16fbd87'] = 'Easing<br>inverso'; // Reverse<br>easing
$_MODULE['<{layerslider}prestashop>_0e95be22e52ba91b2a4eac69dea794c6'] = 'La función de temporización de la animación inversa para manipular el movimiento de la capa. Haz clic en el enlace junto a este campo para abrir easings.net para ejemplos y más información.'; // The timing function of the reverse animation to manipualte the layer's movement. Click on the link next to this field to open easings.net for examples and more information
$_MODULE['<{layerslider}prestashop>_18520e0c41ef4863b7c3d57b41e13dd2'] = 'Rota la capa en el sentido de las agujas del reloj según el número de grados dado. Se permiten valores negativos para la rotación en sentido contrario a las agujas del reloj.'; // Rotates the layer clockwise by the given number of degrees. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_178d558f0ec11adc7f14494caafecfa4'] = 'El color de fondo de esta capa. Puedes usar nombres de colores, valores hexadecimales, RGB o RGBA, así como la palabra clave \'transparent\'. Ejemplo: #FFF'; // The background color of this layer. You can use color names, hexadecimal, RGB or RGBA values as well as the 'transparent' keyword. Example: #FFF
$_MODULE['<{layerslider}prestashop>_7ccb130b01ecf6f307e49d85d78101ae'] = 'El color del texto de este texto. Puedes usar nombres de colores, valores hexadecimales, RGB o RGBA. Ejemplo: #333'; // The text color of this text. You can use color names, hexadecimal, RGB or RGBA values. Example: #333
$_MODULE['<{layerslider}prestashop>_22b4e7bf3118d625243554505037c3d4'] = 'Esquinas redondeadas'; // Rounded corners
$_MODULE['<{layerslider}prestashop>_8baecbc8f47d34ba6f2c94c840039b5d'] = 'Si quieres esquinas redondeadas, puedes establecer aquí su radio en píxeles. Ejemplo: 5px'; // If you want rounded corners, you can set here its radius in pixels. Example: 5px
$_MODULE['<{layerslider}prestashop>_91b9f1c422bb9c80c97c1409c449b01a'] = 'Cambia la perspectiva de las capas en el espacio 3D.'; // Changes the perspective of layers in the 3D space.
$_MODULE['<{layerslider}prestashop>_7b57923badae7705a941c2bb5fdbc259'] = 'Siempre encima'; // Always on top
$_MODULE['<{layerslider}prestashop>_97309a236d6310d21531928e0f237909'] = 'Muestra esta capa por encima de cualquier otra capa al pasar el cursor.'; // Show this layer above every other layer while hovering.
$_MODULE['<{layerslider}prestashop>_b437c451aa3282f75304078beaccd7f2'] = 'Nivel de paralaje'; // Parallax Level
$_MODULE['<{layerslider}prestashop>_6d88cda2a17e8c8ba371534044e4dcac'] = 'Establece la intensidad del efecto de paralaje. Usa valores negativos para desplazar las capas en la dirección opuesta.'; // Set the intensity of the parallax effect. Use negative values to shift layers in the opposite direction.
$_MODULE['<{layerslider}prestashop>_e32aeb1f97bbc4b3734bceba06e62189'] = 'Elige si quieres capas de paralaje 2D o 3D.'; // Choose if you want 2D or 3D parallax layers.
$_MODULE['<{layerslider}prestashop>_db7e7d3165d15f05c446c312cd7ce748'] = 'Heredar de las opciones de la diapositiva'; // Inherit from Slide Options
$_MODULE['<{layerslider}prestashop>_65c19dcd436dba37e3f61abaa74fcb0a'] = 'Puedes activar el efecto de paralaje ya sea desplazando la página, o moviendo el cursor del ratón / inclinando tu dispositivo móvil.'; // You can trigger the parallax effect by either scrolling the page, or by moving your mouse cursor / tilting your mobile device.
$_MODULE['<{layerslider}prestashop>_df4937d57d5546a1b7cad8aa01382a30'] = 'Elige en qué ejes deben moverse las capas de paralaje.'; // Choose on which axes parallax layers should move.
$_MODULE['<{layerslider}prestashop>_130c5b3473c57faa76e2a1c54e26f88e'] = 'Ambos'; // Both
$_MODULE['<{layerslider}prestashop>_f8669b1c29bb1d386ed994a5fa3b2383'] = 'Duración del movimiento'; // Move Duration
$_MODULE['<{layerslider}prestashop>_902394e5c2f298dc004991c64ea639e0'] = 'Controla la velocidad de animación de las capas cuando mueves el cursor del ratón o inclinas tu dispositivo móvil.'; // Controls the speed of animating layers when you move your mouse cursor or tilt your mobile device.
$_MODULE['<{layerslider}prestashop>_e6c62193f078181acd6cc60c21353d08'] = 'Duración de salida'; // Leave Duration
$_MODULE['<{layerslider}prestashop>_387b79d99e6882187a0e3530f37a2f76'] = 'Controla la rapidez con que las capas de paralaje vuelven a su posición original cuando mueves el cursor del ratón fuera del slider. Este valor está en milisegundos. Un segundo equivale a 1000 milisegundos.'; // Controls how quickly parallax layers revert to their original position when you move your mouse cursor outside of the slider. This value is in milliseconds. A second equals to 1000 milliseconds.
$_MODULE['<{layerslider}prestashop>_64a0612acd329567a634da43b59883cf'] = 'Aumenta o disminuye la cantidad de rotación de la capa en el espacio 3D al mover el cursor del ratón o inclinar un dispositivo móvil.'; // Increase or decrease the amount of layer rotation in the 3D space when moving your mouse cursor or tilting on a mobile device.
$_MODULE['<{layerslider}prestashop>_fb86197f4f68b1e2d86783659e7585a3'] = 'Aumenta o disminuye la cantidad de movimiento de la capa al mover el cursor del ratón o inclinar un dispositivo móvil.'; // Increase or decrease the amount of layer movement when moving your mouse cursor or tilting on a mobile device.
$_MODULE['<{layerslider}prestashop>_7b62b4d0a7de4d976159fb96a6fa6411'] = 'Capa estática'; // Static layer
$_MODULE['<{layerslider}prestashop>_9ae2250c53514362ad6490c3431e5464'] = 'Puedes mantener esta capa encima del slider a través de múltiples diapositivas. Simplemente selecciona la diapositiva en la que esta capa debe animarse para salir. Alternativamente, puedes hacer que esta capa sea global en todas las diapositivas después de que haya entrado en transición.'; // You can keep this layer on top of the slider across multiple slides. Just select the slide on which this layer should animate out. Alternatively, you can make this layer global on all slides after it transitioned in.
$_MODULE['<{layerslider}prestashop>_9c2690b8a4048048e2c037e4a03339b0'] = 'Desactivado (predeterminado)'; // Disabled (default)
$_MODULE['<{layerslider}prestashop>_1d7e5793a0150b3c05de1922cc8c16f5'] = 'Activado (nunca se anima para salir)'; // Enabled (never animate out)
$_MODULE['<{layerslider}prestashop>_2a36e79a98871dc76bf33a51af7e3715'] = 'Fotograma clave de reproducción por desplazamiento'; // Play By Scroll Keyframe
$_MODULE['<{layerslider}prestashop>_8e898860158d07998968bfd485788069'] = 'Un slider de reproducción por desplazamiento se pausará cuando esta capa termine su transición de apertura.'; // A Play by Scroll slider will pause when this layer finished its opening transition.
$_MODULE['<{layerslider}prestashop>_627b4c0e8a9b46747497d4bae491a6c2'] = 'Si quieres enlazar tu capa, escribe aquí la URL. Puedes usar un signo de número seguido de un número para enlazar esta capa a otra diapositiva. Ejemplo: #3 - esto cambiará a la tercera diapositiva.'; // If you want to link your layer, type here the URL. You can use a hash mark followed by a number to link this layer to another slide. Example: #3 - this will switch to the third slide.
$_MODULE['<{layerslider}prestashop>_a33a3e8542755c06996a81a78878b66b'] = 'Destino de la URL'; // URL target
$_MODULE['<{layerslider}prestashop>_ba333933886b07c9384523873559a3fd'] = 'Atributos personalizados'; // Custom Attributes
$_MODULE['<{layerslider}prestashop>_a016d8e10948cfc95215918d4372d8f9'] = 'Tu lista de atributos personalizados. Usa esta función si tus necesidades no están cubiertas por los atributos comunes de arriba o si quieres anularlos. Puedes usar data-* así como nombres de atributos regulares. También se permiten atributos vacíos (sin valor). Por ejemplo, para hacer una galería FancyBox, puedes ingresar "data-fancybox-group" y "gallery1" para el nombre y el valor del atributo, respectivamente.'; // Your list of custom attributes. Use this feature if your needs are not covered by the common attributes above or you want to override them. You can use data-* as well as regular attribute names. Empty attributes (without value) are also allowed. For example, to make a FancyBox gallery, you may enter "data-fancybox-group" and "gallery1" for the attribute name and value, respectively.
$_MODULE['<{layerslider}prestashop>_edac8da7d60b7624d4b131bc47a5eb3b'] = 'Puedes establecer el ancho de tu capa. Puedes usar píxeles, porcentaje o el valor predeterminado \'auto\'. Ejemplos: 100px, 50% o auto.'; // You can set the width of your layer. You can use pixels, percentage, or the default value 'auto'. Examples: 100px, 50% or auto.
$_MODULE['<{layerslider}prestashop>_c6272de402f4e075758f7d27f108d6c1'] = 'Puedes establecer la altura de tu capa. Puedes usar píxeles, porcentaje o el valor predeterminado \'auto\'. Ejemplos: 100px, 50% o auto'; // You can set the height of your layer. You can use pixels, percentage, or the default value 'auto'. Examples: 100px, 50% or auto
$_MODULE['<{layerslider}prestashop>_a4ffdcf0dc1f31b9acaf295d75b51d00'] = 'Arriba'; // Top
$_MODULE['<{layerslider}prestashop>_4ce53ede45d38aa6228b7a2e4a9a2d6f'] = 'La posición de la capa desde la parte superior de la diapositiva. Puedes usar píxeles y porcentaje. Ejemplos: 100px o 50%. Puedes mover tus capas en la vista previa de arriba con arrastrar y soltar, o establecer los valores exactos aquí.'; // The layer position from the top of the slide. You can use pixels and percentage. Examples: 100px or 50%. You can move your layers in the preview above with a drag n' drop, or set the exact values here.
$_MODULE['<{layerslider}prestashop>_945d5e233cf7d6240f6b783b36a374ff'] = 'Izquierda'; // Left
$_MODULE['<{layerslider}prestashop>_38ab4523d162374efdee06dcaa89d7dd'] = 'La posición de la capa desde el lado izquierdo de la diapositiva. Puedes usar píxeles y porcentaje. Ejemplos: 100px o 50%. Puedes mover tus capas en la vista previa de arriba con arrastrar y soltar, o establecer los valores exactos aquí.'; // The layer position from the left side of the slide. You can use pixels and percentage. Examples: 100px or 50%. You can move your layers in the preview above with a drag n' drop, or set the exact values here.
$_MODULE['<{layerslider}prestashop>_9bef4210a675b3352481eaba774135e2'] = 'Relleno en la parte superior de la capa. Ejemplo: 10px'; // Padding on the top of the layer. Example: 10px
