$_MODULE['<{layerslider}prestashop>_f8e3211bbd5d1c9e4bbe92fb5006478e'] = 'Estilo de fuente'; // Font style
$_MODULE['<{layerslider}prestashop>_935d167268be2e114d55069d55e1a408'] = 'Oblicua es una versión en cursiva generada automáticamente de la fuente elegida y puede forzar la inclinación incluso si no hay una variante de fuente en cursiva disponible. Sin embargo, debes usar la opción de cursiva regular siempre que sea posible. Por favor, verifica dos veces para cargar variantes de fuente en cursiva al usar Google Fonts.'; // Oblique is an auto-generated italic version of your chosen font and can force slating even if there is no italic font variant available. However, you should use the regular italic option whenever is possible. Please double check to load italic font variants when using Google Fonts.
$_MODULE['<{layerslider}prestashop>_1d874710ccdcd46b95397049d2e7500c'] = 'Cursiva'; // Italic
$_MODULE['<{layerslider}prestashop>_aa2870bb0730c19998358f5cdbc0dc1b'] = 'Oblicua (inclinación forzada)'; // Oblique (Forced slant)
