$_MODULE['<{layerslider}prestashop>_6d40b0cbf0593b752ece63f7a9928eef'] = 'Controla la cantidad de espacio entre cada carácter. Útil para cambiar la densidad de las letras en una línea o bloque de texto. Se pueden usar valores negativos y decimales.'; // Controls the amount of space between each character. Useful the change letter density in a line or block of text. Negative values and decimals can be used.
$_MODULE['<{layerslider}prestashop>_c22b28c5c38d219b521e476691bd7158'] = 'Alineación del texto'; // Text align
$_MODULE['<{layerslider}prestashop>_6c982f951a9fa0736c853e9353ff1553'] = 'Inicial (predeterminado del idioma)'; // Initial (Language default)
$_MODULE['<{layerslider}prestashop>_4f1f6016fc9f3f2353c0cc7c67b292bd'] = 'Centro'; // Center
$_MODULE['<{layerslider}prestashop>_4b425d212a2e7b36c38703bfdcd57823'] = 'Justificar'; // Justify
$_MODULE['<{layerslider}prestashop>_a8bc50a5bb0ee94aef28600eeccfaa60'] = 'Tamaño de fuente mín.'; // Min. font size
$_MODULE['<{layerslider}prestashop>_cd7ab6145e3bf89a25e376abd17ab01e'] = 'El tamaño de fuente mínimo en un slider responsive. Esta opción te permite evitar que tus capas de texto se vuelvan demasiado pequeñas en pantallas más pequeñas.'; // The minimum font size in a responsive slider. This option allows you to prevent your texts layers becoming too small on smaller screens.
$_MODULE['<{layerslider}prestashop>_e0bc0f8bfc07dfaa60de8a19a075ecaf'] = 'Tamaño de fuente mín. móvil'; // Min. mobile font size
$_MODULE['<{layerslider}prestashop>_56cac8df2a819eb309f656bec767e641'] = 'El tamaño de fuente mínimo en un slider responsive en dispositivos móviles. Esta opción te permite evitar que tus capas de texto se vuelvan demasiado pequeñas en pantallas más pequeñas.'; // The minimum font size in a responsive slider on mobile devices. This option allows you to prevent your texts layers becoming too small on smaller screens.
$_MODULE['<{layerslider}prestashop>_ee0b6a872572cc985f1d5d20a5901ffb'] = 'Si quieres esquinas redondeadas, puedes establecer su radio aquí. Ejemplo: 5px'; // If you want rounded corners, you can set its radius here. Example: 5px
$_MODULE['<{layerslider}prestashop>_856ba67470300f8246b140de9a27555d'] = 'Estilos personalizados'; // Custom styles
$_MODULE['<{layerslider}prestashop>_7e045337d227fc13f0b7efdadf341169'] = 'Si quieres establecer configuraciones de estilo distintas a las anteriores, puedes usar aquí cualquier código CSS. Asegúrate de escribir un marcado válido.'; // If you want to set style settings other than above, you can use here any CSS codes. Please make sure to write valid markup.
$_MODULE['<{layerslider}prestashop>_3dbe275d40b3a2b680bdfa25242cc8fe'] = 'El ángulo de rotación hacia el que se anima esta capa al entrar en el lienzo del slider. Se permiten valores negativos para la rotación en sentido contrario a las agujas del reloj.'; // The rotation angle where this layer animates toward when entering into the slider canvas. Negative values are allowed for counterclockwise rotation.
$_MODULE['<{layerslider}prestashop>_fe75b60943091f007ae820a3188868a2'] = 'El ángulo de rotación en el eje horizontal hacia el que se anima al entrar en el lienzo del slider. Se permiten valores negativos para la dirección inversa.'; // The rotation angle on the horizontal axis where this animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_0c6a5ad5f832c1f79c4b4d62fee16e26'] = 'El ángulo de rotación en el eje vertical hacia el que se anima esta capa al entrar en el lienzo del slider. Se permiten valores negativos para la dirección inversa.'; // The rotation angle on the vertical axis where this layer animates toward when entering into the slider canvas. Negative values are allowed for reversed direction.
$_MODULE['<{layerslider}prestashop>_6af83f149c018cdec1dba351c619b7ca'] = 'La escala horizontal de la capa hacia la que se anima esta capa al entrar en el lienzo del slider.'; // The layer horizontal scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_28d8b2ec189dc2eb778a851265cf4f26'] = 'La escala vertical de la capa hacia la que se anima esta capa al entrar en el lienzo del slider.'; // The layer vertical scale where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_63d48e08093f6964b3cdc6d33740663e'] = 'El ángulo de inclinación horizontal de la capa hacia el que se anima esta capa al entrar en el lienzo del slider.'; // The layer horizontal skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_e4b23d4080824b973029720a307cbae6'] = 'El ángulo de inclinación vertical de la capa hacia el que se anima esta capa al entrar en el lienzo del slider.'; // The layer vertical skewing angle where this layer animates toward when entering into the slider canvas.
$_MODULE['<{layerslider}prestashop>_45f908bb74a7835d23630c7d51031fed'] = 'Calcular posiciones desde'; // Calculate positions from
$_MODULE['<{layerslider}prestashop>_639b76980c25ea95700d2c2e96833964'] = 'Establece el origen de la posición de la capa desde el cual se calculan los valores superior e izquierdo. El predeterminado es la esquina superior izquierda del lienzo del slider. En un slider de ancho completo y tamaño completo, tu contenido se centra según el tamaño de la pantalla para lograr el mejor ajuste posible. Al seleccionar la opción "lados de la pantalla" en esos escenarios, puedes permitir que las capas escapen del área interna centrada y se peguen a los lados de la pantalla.'; // Sets the layer position origin from which top and left values are calculated. The default is the upper left corner of the slider canvas. In a full width and full size slider, your content is centered based on the screen size to achieve the best possible fit. By selecting the "sides of the screen" option in those scenarios, you can allow layers to escape the centered inner area and stick to the sides of the screen.
$_MODULE['<{layerslider}prestashop>_b16710c8d62abca1ccda544c63bea7e8'] = 'lados del slider'; // sides of the slider
$_MODULE['<{layerslider}prestashop>_ab761fc53dc83dca5a36b9a25bf548bf'] = 'lados de la pantalla'; // sides of the screen
$_MODULE['<{layerslider}prestashop>_51400b417ad07f539ecfd9469027a5b6'] = 'Orden de apilamiento'; // Stacking order
$_MODULE['<{layerslider}prestashop>_4c26a68fa7463987e86f61733caf8491'] = 'Esta opción controla el orden de apilamiento vertical de las capas que se superponen. En CSS, comúnmente se le llama z-index. Los elementos con un valor más alto se apilan frente a los elementos con uno más bajo, cubriéndolos eficazmente. Por defecto, este valor se calcula automáticamente en función del orden de tus capas, por lo que simplemente reordenarlas puede solucionar problemas de superposición. Usa esta opción solo si quieres establecer tu propio valor manualmente en casos especiales como el uso de capas estáticas.<br><br>En cada diapositiva, el orden de apilamiento comienza a contar desde 100. Proporcionar un número menor que 100 pondrá la capa detrás de todas las demás capas en todas las diapositivas. Especificar un número mucho mayor, por ejemplo 500, hará que la capa esté encima de todo lo demás.'; // This option controls the vertical stacking order of layers that overlap. In CSS, it's commonly called as z-index. Elements with a higher value are stacked in front of elements with a lower one, effectively covering them. By default, this value is calculated automatically based on the order of your layers, thus simply re-ordering them can fix overlap issues. Use this option only if you want to set your own value manually in special cases like using static layers.<br><br>On each slide, the stacking order starts counting from 100. Providing a number less than 100 will put the layer behind every other layer on all slides. Specifying a much greater number, for example 500, will make the layer to be on top of everything else.
$_MODULE['<{layerslider}prestashop>_0c301043ef92f5854d711e54f96a86c5'] = 'Modo de fusión'; // Blend mode
$_MODULE['<{layerslider}prestashop>_df5c4d0c2cd9156afa20fa59c572acde'] = 'Elige cómo las capas y el fondo de la diapositiva deben fusionarse entre sí. Los modos de fusión son una forma fácil de agregar efectos llamativos y es una de las características más utilizadas en el diseño gráfico e impreso.'; // Choose how layers and the slide background should blend into each other. Blend modes are an easy way to add eye-catching effects and is one of the most frequently used features in graphic and print design.
$_MODULE['<{layerslider}prestashop>_b718adec73e04ce3ec720dd11a06a308'] = 'ID'; // ID
$_MODULE['<{layerslider}prestashop>_ca79528715d6c07cb429e8189105cbb4'] = 'Puedes aplicar un atributo ID en el elemento HTML de esta capa para trabajar con él en tu código CSS o Javascript personalizado.'; // You can apply an ID attribute on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_e9878b4854d29907146149f695cb1cfb'] = 'Clases'; // Classes
$_MODULE['<{layerslider}prestashop>_c666f7b19a598af3cadb8c9cb07c4bcd'] = 'Puedes aplicar clases en el elemento HTML de esta capa para trabajar con él en tu código CSS o Javascript personalizado.'; // You can apply classes on the HTML element of this layer to work with it in your custom CSS or Javascript code.
$_MODULE['<{layerslider}prestashop>_3ace045d5becea8953aabde365c5c8d8'] = 'Puedes agregar un título a esta capa que se mostrará como una información sobre herramientas si alguien mantiene el cursor del ratón sobre la capa.'; // You can add a title to this layer which will display as a tooltip if someone holds his mouse cursor over the layer.
$_MODULE['<{layerslider}prestashop>_f2364c335fe8ae15c8d64b2744db0f40'] = 'Nombra o describe tu capa de imagen, para que los motores de búsqueda y los programas de lectura de pantalla puedan identificarla correctamente.'; // Name or describe your image layer, so search engines and VoiceOver softwares can properly identify it.
$_MODULE['<{layerslider}prestashop>_eba991d56b1be0b940d722211bab87bc'] = 'Rel'; // Rel
$_MODULE['<{layerslider}prestashop>_b987cf5b1aa6af2a92b97f69d65c29df'] = 'Los plugins y los motores de búsqueda pueden usar este atributo para obtener más información sobre el rol y el comportamiento de un enlace.'; // Plugins and search engines may use this attribute to get more information about the role and behavior of a link.
$_MODULE['<{layerslider}prestashop>_5d083603a18046659c2b4b23af7948cc'] = 'Opción avanzada'; // Advanced option
$_MODULE['<{layerslider}prestashop>_31fde7b05ac8952dacf4af8a704074ec'] = 'Vista previa'; // Preview
$_MODULE['<{layerslider}prestashop>_a67f2c9d056f29b94521c17b838b9756'] = 'Mosaicos'; // Tiles
$_MODULE['<{layerslider}prestashop>_530f488f7a9800411efc6926ab189708'] = 'Filas'; // Rows
$_MODULE['<{layerslider}prestashop>_35b93b52adc0893d6f4b32752660535f'] = '<i>número</i> o <i>mín,máx</i> Si especificas un valor mayor que 1, Creative Slider cortará tu diapositiva en mosaicos. Puedes especificar aquí cuántas filas debe tener tu transición. Si especificas dos números separados por una coma, Creative Slider lo usará como un rango y elegirá un número aleatorio entre tus valores.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many rows of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_d27561f45c58f407b3fe76b63b1ec28a'] = 'Cols'; // Cols
$_MODULE['<{layerslider}prestashop>_a122bf49cbf8c9cf02971a495e81ed16'] = '<i>número</i> o <i>mín,máx</i> Si especificas un valor mayor que 1, Creative Slider cortará tu diapositiva en mosaicos. Puedes especificar aquí cuántas columnas debe tener tu transición. Si especificas dos números separados por una coma, Creative Slider lo usará como un rango y elegirá un número aleatorio entre tus valores.'; // <i>number</i> or <i>min,max</i> If you specify a value greater than 1, Creative Slider will cut your slide into tiles. You can specify here how many columns of your transition should have. If you specify two numbers separated with a comma, Creative Slider will use that as a range and pick a random number between your values.
$_MODULE['<{layerslider}prestashop>_8f497c1a3d15af9e0c215019f26b887d'] = 'Retraso'; // Delay
$_MODULE['<{layerslider}prestashop>_d4f0208d1a34d7a381fc8abec990105b'] = 'Puedes aplicar un retraso entre los mosaicos y posponer su animación en relación unos con otros.'; // You can apply a delay between the tiles and postpone their animation relative to each other.
$_MODULE['<{layerslider}prestashop>_3ff39d3acb327553070a64ef0cb321d5'] = 'Secuencia'; // Sequence
$_MODULE['<{layerslider}prestashop>_434cd8b268e79b39af562cc6329d56fb'] = 'Puedes controlar el orden de la animación de los mosaicos aquí.'; // You can control the animation order of the tiles here.
$_MODULE['<{layerslider}prestashop>_67d2f6740a8eaebf4d5c6f79be8da481'] = 'Adelante'; // Forward
$_MODULE['<{layerslider}prestashop>_67f115c1fddc4ce1aeb1c754001585bc'] = 'Inverso'; // Reverse
$_MODULE['<{layerslider}prestashop>_13db785ec723ba5b44f1a1311edc9332'] = 'Col-adelante'; // Col-forward
$_MODULE['<{layerslider}prestashop>_3898dd1cf4144fda9dfac68e6c3b7c41'] = 'Col-inverso'; // Col-reverse
$_MODULE['<{layerslider}prestashop>_afedf9afee367f51f98d7cf030c976a6'] = 'Transición'; // Transition
$_MODULE['<{layerslider}prestashop>_1f3b894b65d30b6d1f137f4b4dad7823'] = 'La duración de la animación. Este valor está en milisegundos, por lo que el valor 1000 significa 1 segundo.'; // The duration of the animation. This value is in millisecs, so the value 1000 measn 1 second.
$_MODULE['<{layerslider}prestashop>_639a36a8fd5673fccfa75e572ca859f7'] = 'El tipo de animación, ya sea deslizamiento, fundido o ambos (mixto).'; // The type of the animation, either slide, fade or both (mixed).
$_MODULE['<{layerslider}prestashop>_6160a53ece50ce6d4f5ef4452549835e'] = 'Deslizar'; // Slide
