$_MODULE['<{layerslider}prestashop>_9a58721d33e670fce7361aa9e3d9ff70'] = 'Empieza cuando'; // Start when
$_MODULE['<{layerslider}prestashop>_4d08efe2791a677104f296ad0a66b05b'] = 'Desplaza la hora de inicio seleccionada anteriormente realizando una operación personalizada. Por ejemplo, "- 1000" adelantará la animación reproduciéndola 1 segundo (1000 milisegundos) antes.'; // Shifts the above selected starting time by performing a custom operation. For example, "- 1000" will advance the animation by playing it 1 second (1000 milliseconds) earlier.
