$_MODULE['<{layerslider}prestashop>_fb1eb0bc378ca1a36b8f1af434973cdb'] = 'Repite una transición basada en las opciones a continuación. Si estableces el Conteo de Bucle en 1, también puede actuar como una transición intermedia en la cadena de ciclos de vida de la animación.'; // Repeats a transition based on the options below. If you set the Loop Count to 1, it can also act as a middle transition in the chain of animation lifecycles.
$_MODULE['<{layerslider}prestashop>_a9aad76491b11de0946f522d395fddc6'] = 'Cada fragmento de texto se animará desde la palabra completa conjunta hacia las opciones que especifiques aquí.'; // Each text fragment will animate from the joint whole word to the options you specify here.
