$_MODULE['<{layerslider}prestashop>_5176d5116bcd3d0b01d5402c68cc0ebf'] = 'Ahora puedes retroceder en el tiempo'; // You Can Now Rewind Time
$_MODULE['<{layerslider}prestashop>_04099750838e0b2fc6c9d68c5dc47b42'] = 'Ten la tranquilidad de saber que las ediciones de tu slider siempre están seguras y puedes revertir cambios no deseados o guardados defectuosos en cualquier momento. Esta función no solo sirve como una solución de respaldo, sino como un sistema completo de control de versiones donde puedes comparar visualmente los cambios que has realizado en el camino.'; // Have a peace of mind knowing that your slider edits are always safe and you can revert back unwanted changes or faulty saves at any time. This feature serves not just as a backup solution, but a complete version control system where you can visually compare the changes you have made along the way.
$_MODULE['<{layerslider}prestashop>_3a06c5ff9c120c2e7e49750f76c3b0c9'] = 'Personalizar las Preferencias de Revisiones'; // Customize Revisions Preferences
