$_MODULE['<{layerslider}prestashop>_85e5569165918988076ed20f567709ab'] = 'Esperar al menos %s minutos entre ediciones antes de añadir una nueva revisión.'; // Wait at least %s minutes between edits before adding a new revision.
$_MODULE['<{layerslider}prestashop>_a79dc794e7af45729dfba74a532f0ad6'] = 'Las Revisiones del Slider también almacenan los controles de deshacer/rehacer. No hay razón para usar guardados muy frecuentes ya que podrás deshacer los cambios intermedios.'; // Slider Revisions also stores the undo/redo controls. There is no reason using very frequent saves since you will be able to undo the changes in-between.
