$_MODULE['<{layerslider}prestashop>_dae53216ad3909742ad508599f4f524c'] = 'Los efectos especiales son como las transiciones de diapositivas normales y funcionan de la misma manera. Puedes establecerlos en cada diapositiva individualmente. Mezclarlos con otras transiciones en otras diapositivas está perfectamente bien. También puedes aplicarlos a todas tus diapositivas a la vez presionando el botón "Aplicar a otros" de arriba. En el caso de los efectos especiales 3D, seleccionar transiciones 2D adicionales puede garantizar la compatibilidad con navegadores más antiguos.'; // Special effects are like regular slide transitions and they work in the same way. You can set them on each slide individually. Mixing them with other transitions on other slides is perfectly fine. You can also apply them on all of your slides at once by pressing the "Apply to others" button above. In case of 3D special effects, selecting additional 2D transitions can ensure backward compatibility for older browsers.
$_MODULE['<{layerslider}prestashop>_b8855caaf641a9f8cd794b263fd3187f'] = 'Transición Origami'; // Origami transition
$_MODULE['<{layerslider}prestashop>_120a5b58df4cf329020874fee6e1a01c'] = 'Comparte tus magníficas fotos con el mundo o tus seres queridos de una manera verdaderamente inspiradora y crea sliders con efectos impresionantes con Origami.'; // Share your gorgeous photos with the world or your loved ones in a truly inspirational way and create sliders with stunning effects with Origami.
$_MODULE['<{layerslider}prestashop>_2b0cda1ac8369a2372e2de48907dabc4'] = 'Origami es una forma de transición 3D y funciona de la misma manera que las transiciones de diapositivas normales. Además de Internet Explorer, Origami funciona en todos los navegadores modernos (incluido Edge).'; // Origami is a form of 3D transition and it works in the same way as regular slide transitions do. Besides Internet Explorer, Origami works in all the modern browsers (including Edge).
$_MODULE['<{layerslider}prestashop>_d8051901953ab9ec06e0bd5e929da146'] = 'Usarlo en esta diapositiva'; // Use it on this slide
